<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();$q=$db->prepare('SELECT m.id,m.subject,m.body,m.created_at,m.is_read,u.username sender FROM private_messages m JOIN users u ON u.id=m.sender_id WHERE m.recipient_id=? ORDER BY m.id DESC LIMIT 100');$q->execute([$currentUser['id']]);$messages=$q->fetchAll();page_start('Inbox');?><section class="Panel"><h1>Inbox</h1><p><a href="/My/PrivateMessage.php">Compose message</a></p><table class="Grid"><tr><th>Subject</th><th>From</th><th>Date</th><th>Status</th></tr><?php foreach($messages as $m):?><tr><td><a href="/My/PrivateMessage.php?id=<?=(int)$m['id']?>"><?=e($m['subject'])?></a></td><td><?=e($m['sender'])?></td><td><?=e($m['created_at'])?></td><td><?=$m['is_read']?'Read':'New'?></td></tr><?php endforeach;?><?php if(!$messages):?><tr><td colspan="4">Your inbox is empty.</td></tr><?php endif;?></table></section><?php page_end();